import { View, Text, StyleSheet } from "react-native";
import { registerRootComponent } from "expo";

function App() {
  return (
    <View style={styles.screen}>
      <View nativeID="card" style={styles.card}>
        <Text style={styles.name}>Гар цаг X100</Text>
        <Text style={styles.status}>Дууссан</Text>
      </View>
      {/* энд бичнэ үү: дууссан картыг бүдгэрүүл */}
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, padding: 24, justifyContent: "center" },
  card: { backgroundColor: "#fff", padding: 20, borderRadius: 16, gap: 6, elevation: 4 },
  name: { fontSize: 16, fontWeight: "600" },
  status: { color: "#dc2626", fontWeight: "bold" },
});

registerRootComponent(App);

